// Define a simple Matrix struct to wrap a 2D vector
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Matrix<T> {
    data: Vec<Vec<T>>,
    rows: usize,
    cols: usize,
}

impl<T> Matrix<T> {
    // Helper method to create a new matrix
    fn new(data: Vec<Vec<T>>, rows: usize, cols: usize) -> Self {
        Self { data, rows, cols }
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Validate assumptions
    assert!(!a.is_empty(), "Input array must have positive length");
    assert_eq!(shape.len(), 2, "Shape array must have length exactly 2");
    
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    assert!(r > 0 && c > 0, "Both shape entries must be positive");
    assert!(
        a.len() == r || a.len() == c,
        "Array length must equal either R or C"
    );
    
    let mut result = Vec::with_capacity(r);
    
    if a.len() == r {
        // Treat as column vector: each element of 'a' becomes a row
        // where all columns have the same value (the element)
        for &element in &a {
            let row = vec![element; c];
            result.push(row);
        }
    } else { // a.len() == c
        // Treat as row vector: copy the entire array for each row
        for _ in 0..r {
            result.push(a.clone());
        }
    }
    
    Matrix::new(result, r, c)
}